CREATE TABLE users (user_id SERIAL PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, password_hash TEXT NOT NULL, role VARCHAR(20) NOT NULL CHECK (role IN ('analyst','administrator','reviewer')));
CREATE TABLE datasets (dataset_id SERIAL PRIMARY KEY, user_id INT NOT NULL REFERENCES users(user_id), name VARCHAR(150) NOT NULL, source VARCHAR(200), row_count INT CHECK (row_count >= 0), created_at TIMESTAMP DEFAULT now(), UNIQUE (user_id, name));
CREATE TABLE features (feature_id SERIAL PRIMARY KEY, dataset_id INT NOT NULL REFERENCES datasets(dataset_id) ON DELETE CASCADE, name VARCHAR(100) NOT NULL, type VARCHAR(20) NOT NULL CHECK (type IN ('numerical','categorical')), reference_stats JSONB, UNIQUE (dataset_id, name));
CREATE TABLE models (model_id SERIAL PRIMARY KEY, dataset_id INT NOT NULL REFERENCES datasets(dataset_id), algorithm VARCHAR(50) NOT NULL, version INT NOT NULL, status VARCHAR(20) NOT NULL CHECK (status IN ('champion','challenger','retired')), metrics JSONB, trained_at TIMESTAMP DEFAULT now(), UNIQUE (dataset_id, algorithm, version));
CREATE TABLE monitoring_jobs (job_id SERIAL PRIMARY KEY, model_id INT NOT NULL REFERENCES models(model_id), user_id INT NOT NULL REFERENCES users(user_id), batch_id VARCHAR(64) NOT NULL, window_start TIMESTAMP NOT NULL, window_end TIMESTAMP NOT NULL, status VARCHAR(20) NOT NULL, CHECK (window_end >= window_start));
CREATE TABLE drift_summaries (summary_id SERIAL PRIMARY KEY, job_id INT NOT NULL REFERENCES monitoring_jobs(job_id) ON DELETE CASCADE, feature_id INT NOT NULL REFERENCES features(feature_id), psi REAL, ks_stat REAL, ks_p REAL, jsd REAL, dis REAL, severity VARCHAR(10) CHECK (severity IN ('low','moderate','high')), UNIQUE (job_id, feature_id));
CREATE TABLE alerts (alert_id SERIAL PRIMARY KEY, job_id INT NOT NULL REFERENCES monitoring_jobs(job_id), alert_type VARCHAR(30) NOT NULL CHECK (alert_type IN ('drift-warning','confirmed-degradation')), level VARCHAR(10) NOT NULL, recommendation TEXT, created_at TIMESTAMP DEFAULT now());
CREATE TABLE retraining_events (event_id SERIAL PRIMARY KEY, alert_id INT REFERENCES alerts(alert_id), old_model_id INT NOT NULL REFERENCES models(model_id), new_model_id INT NOT NULL REFERENCES models(model_id), decision VARCHAR(20) NOT NULL CHECK (decision IN ('pending','deployed','rejected','rolled_back')), rollback_flag BOOLEAN DEFAULT FALSE, created_at TIMESTAMP DEFAULT now(), CHECK (old_model_id <> new_model_id));
CREATE TABLE thresholds (threshold_id SERIAL PRIMARY KEY, name VARCHAR(60) NOT NULL UNIQUE, value DOUBLE PRECISION NOT NULL, updated_by INT REFERENCES users(user_id), updated_at TIMESTAMP DEFAULT now());
CREATE TABLE threshold_history (history_id SERIAL PRIMARY KEY, name VARCHAR(60) NOT NULL, old_value DOUBLE PRECISION, new_value DOUBLE PRECISION NOT NULL, changed_by INT REFERENCES users(user_id), changed_at TIMESTAMP DEFAULT now());
CREATE INDEX drift_summaries_job_id ON drift_summaries(job_id); CREATE INDEX monitoring_jobs_model_window ON monitoring_jobs(model_id, window_start); CREATE INDEX alerts_job_created ON alerts(job_id, created_at); CREATE UNIQUE INDEX one_champion_per_dataset ON models(dataset_id) WHERE status='champion';
